 if(language==='csharp')return 'static System.Collections.Generic.List<int> ctFilled(int n, int value) { var outValue = new System.Collections.Generic.List<int>(); for (int i=0; i<n; i++) outValue.Add(value); return outValue; }\n';
 if(language==='java')return 'static java.util.ArrayList<Integer> ctFilled(int n, int value) { java.util.ArrayList<Integer> outValue = new java.util.ArrayList<Integer>(); for (int i=0; i<n; i++) outValue.add(value); return outValue; }\n';
 if(language==='go')return 'func ctFilled(n int, value int) []int { outValue := []int{}; for i:=0; i<n; i++ { outValue=append(outValue,value) }; return outValue }\nfunc ctMin(a int,b int) int { if a<b { return a }; return b }\nfunc ctMax(a int,b int) int { if a>b { return a }; return b }\nfunc ctAbs(a int) int { if a<0 { return -a }; return a }\n';
