function ioHarness(quiz,submitted){
 const calls=quiz.cases.map(c=>`${quiz.functionName}(${c.args.map((a,i)=>literalFor(quiz.language,a,quiz.parameters[i].type)).join(', ')})`);
 let source;
 if(quiz.language==='cpp')source='#include <iostream>\n'+submitted+CPP_PRINT+'\nint main(){\n'+calls.map(call=>`ctPrint(${call});`).join('\n')+'\n}\n';
 else if(quiz.language==='csharp')source='class Program {\n'+submitted+CS_PRINT+'\nstatic void Main(string[] args){\n'+calls.map(call=>`ctPrint(${call});`).join('\n')+'\n}\n}\n';
 else if(quiz.language==='java')source='public class Main {\n'+submitted+JAVA_PRINT+'\npublic static void main(String[] args){\n'+calls.map(call=>`ctPrint(${call});`).join('\n')+'\n}\n}\n';
 else if(quiz.language==='rust')source=submitted+RUST_PRINT+'\nfn main(){\n'+calls.map(call=>quiz.resultType==='string'?`ct_print_string(${call});`:`println!("{:?}", ${call});`).join('\n')+'\n}\n';
 else if(quiz.language==='go')source='package main\nimport "fmt"\n'+submitted+GO_PRINT+'\nfunc main(){\n'+calls.map(call=>`${quiz.resultType==='array'?'ctPrintArray':quiz.resultType==='string'?'ctPrintString':'fmt.Println'}(${call})`).join('\n')+'\n}\n';
 else if(quiz.language==='python')source='import json\n'+submitted+'\n'+calls.map(call=>`print(json.dumps(${call}, ensure_ascii=True))`).join('\n')+'\n';
 else source=submitted+LUA_PRINT+'\n'+calls.map(call=>`print(ctJSON(${call}))`).join('\n')+'\n';
 return {language:quiz.language,source,outputFormat:'json-lines',expected:quiz.cases.map(c=>c.expected),caseIds:quiz.cases.map(c=>c.id),...(quiz.language==='java'?{fileName:'Main.java'}:{})};
}
