function inputContract(def){
 const names=def.parameters.map(p=>p.name),notes=[];
 if(names.includes('nodes'))notes.push('nodesは0以上。edgesの各頂点番号は0以上nodes未満で、有効な頂点だけを与えます。辺の列長は'+(def.slug==='weighted-paths'?'3':'2')+'の倍数です。'+(names.includes('start')?'nodes>0のときstartは有効な頂点番号です。':''));
 if(names.includes('grid'))notes.push(names.includes('height')?'width,heightは0以上で、gridの長さはwidth×heightです。空画像以外では幅と高さは正です。'+(names.includes('start')?'空でない画像のstartはgrid内の有効な添字です。':''):'widthは0以上で、gridの長さはwidth×widthです。');
 if(names.includes('points'))notes.push(def.slug==='bresenham-line'?'pointsの長さは4です。':'pointsの長さは偶数で、各2要素が一つの点または速度を表します。');
 if(def.slug==='nearest-color-index')notes.push('valuesの長さは3の倍数、foregroundの長さは3で、全色成分は0..255です。');
 if(names.includes('intervals'))notes.push('intervalsの長さは偶数で、各開始値は対応する終了値以下です。');
 return notes.length?' '+notes.join(' '):'';
}
