export function challengeTopics(language,subject){
 if(!CHALLENGE_LANGUAGES.includes(language))throw new RangeError(`Unsupported challenge language: ${language}`);
 if(!CHALLENGE_SUBJECTS.includes(subject))throw new RangeError(`Unsupported challenge subject: ${subject}`);
 const old=Array.from({length:16},(_,index)=>wrapLegacy(quizAt(language,subject,index)));
 const added=language==='sql'?sqlQuestions(subject).map((q,i)=>buildSQL(q,16+i)):defs.filter(d=>d.subject===subject).map((d,i)=>buildIO(language,d,16+i));
 return [...old,...added];
}
export function challengeAt(language,subject,index=0){const topics=challengeTopics(language,subject),n=Number.isFinite(index)?Math.max(0,Math.floor(index))%topics.length:0;return topics[n];}
export function challengeById(id){
 if(typeof id!=='string')return null;
 if(cache.has(id))return cache.get(id);
 const old=quizById(id);if(old)return wrapLegacy(old);
 const parts=id.split('/');if(parts.length!==5||parts[0]!=='challenge'||parts[1]!=='v1'||!CHALLENGE_LANGUAGES.includes(parts[2])||!CHALLENGE_SUBJECTS.includes(parts[3]))return null;
 return challengeTopics(parts[2],parts[3]).find(q=>q.id===id) || null;
}
export function challengeCatalog(){return CHALLENGE_LANGUAGES.flatMap(language=>CHALLENGE_SUBJECTS.flatMap(subject=>challengeTopics(language,subject)));}
